<?php
    $filename = pathinfo($file, PATHINFO_FILENAME);
    enqueue_block_assets($filename);
    
    $map_title = get_field('map_title');
    $map_text  = get_field('map_text');
    $map_link  = get_field('map_link');

    // Styles
    $map_active   = get_sub_field('map_active');
    $map_padding  = get_sub_field('map_padding');

    if(empty($map_title)) {
        $map_title = get_field('map_title', 'option');
    } 
    if(empty($map_text)) {
        $map_text = get_field('map_text', 'option');
    } 
    if(empty($map_link)) {
        $map_link = get_field('map_link', 'option');
    } 



    // Récupérer toutes les régions
    $regions = get_terms(array(
        'taxonomy' => 'region',
        'hide_empty' => false, // Pour afficher toutes les régions, même sans post
    ));

    $types_to_count = array(
        'formations',       // slug du terme Formations
        'offres-demploi'   // slug du terme Offres d'emploi
    );

    $results = array();

    // Parcourir chaque région
    foreach ($regions as $region) {
        $results[$region->slug] = array();

        foreach ($types_to_count as $type_slug) {
            // Récupérer le terme de la taxonomie types
            $type_term = get_term_by('slug', $type_slug, 'type_opportunite');
            if (!$type_term) continue;

            // Requête WP pour compter les posts
            $query = new WP_Query(array(
                'post_type' => 'carriere',
                'posts_per_page' => -1,
                'tax_query' => array(
                    'relation' => 'AND',
                    array(
                        'taxonomy' => 'type_opportunite',
                        'field' => 'term_id',
                        'terms' => $type_term->term_id,
                    ),
                    array(
                        'taxonomy' => 'region',
                        'field' => 'term_id',
                        'terms' => $region->term_id,
                    ),
                ),
                'fields' => 'ids', // On récupère seulement les IDs pour optimiser
            ));

            $results[$region->slug][$type_slug] = $query->found_posts;
        }
    }

   if($map_active) :
?>

